import {normalizeStockPurchasing,SUPPLY_KINDS} from './tank-stock-supply.js';
import {TANK_STOCKS,materialKey} from './tank-stock-config.js';
import {compareStockPurchases,applyPurchaseOption,supplyLines} from './tank-stock-cost.js';
import {esc,fmt} from './tank-visuals.js';
export const money=(n,currency='TWD')=>Number.isFinite(n)?currency+' '+Number(n).toLocaleString('zh-TW',{minimumFractionDigits:2,maximumFractionDigits:2}):'待報價';
const mass=n=>Number.isFinite(n)?fmt(n,2)+' kg':'重量待填密度';
const val=n=>n??'';
export function supplyOptionMarkup(item,currency){
  return `<div class="supply-options">${item.options.map(o=>`<article class="supply-option ${item.best===o?'is-best':''}"><header><h4>${esc(o.name)}</h4>${item.best===o?'<span>已報價中較省</span>':''}</header>${o.feasible?`<strong class="supply-price">${money(o.cost,currency)}</strong><p>${o.sheetCount} 張／片 · ${mass(o.weight)}</p><dl><div><dt>餘料＋損耗</dt><dd>${mass(o.offcutWeight)}</dd></div><div><dt>可保留矩形餘板</dt><dd>${fmt(o.freeArea/1e6,3)} m²</dd></div><div><dt>全槽已知焊長</dt><dd>${fmt(o.knownWeldLength/1000,2)} m${o.knownWeldLength>item.baselineWeld+1e-6?' <b>＋'+fmt((o.knownWeldLength-item.baselineWeld)/1000,2)+' m</b>':''}</dd></div></dl><details><summary>看買哪幾筆料與剩餘數量</summary><ul>${o.lines.map(l=>`<li><strong>${esc(l.id+' '+(l.name||SUPPLY_KINDS[l.kind]))}</strong><span>${fmt(l.length)} × ${fmt(l.width)} mm · ${l.used} 片</span><span>${money(l.unitPrice,currency)}／片${l.fee?'，另收 '+money(l.fee,currency)+'／筆':''}</span><span>小計 ${money(l.subtotal,currency)} · ${l.remaining===null?'整張供應不限量':'供料尚餘 '+l.remaining+' 片'}</span></li>`).join('')}</ul><p>分片基準 ${fmt(o.development.stockLength)} × ${fmt(o.development.stockWidth)} mm${o.automatic?'；筒身 '+o.courses+' 圈 × '+o.panelsPerCourse+' 片':''}。${o.largestFree?'最大矩形餘板 '+fmt(o.largestFree.w)+' × '+fmt(o.largestFree.h)+' mm。':''}</p></details><button type="button" data-supply-apply="${encodeURIComponent(item.group.selectionKey)}" data-mode="${o.mode}">採用這個採購排法 →</button>`:`<p class="supply-unavailable">${esc(o.reason)}</p><button type="button" data-supply-edit-group="${encodeURIComponent(item.group.selectionKey)}" class="tank-secondary">補這組料源／報價</button>`}</article>`).join('')}</div>`;
}
export class TankStockSupplyUI{
  constructor({root,onChange,onApply,notify}){this.root=root;this.onChange=onChange;this.onApply=onApply;this.notify=notify;this.data=normalizeStockPurchasing().data;this.selected='';this.groupKey='';this.tab='quotes';this.model=null;this.extraOpen=new Set();this.showAll=false;root.addEventListener('click',e=>this.click(e));root.addEventListener('input',e=>this.edit(e,false));root.addEventListener('change',e=>this.edit(e,true));}
  values(){return structuredClone(this.data);}
  apply(raw){this.data=normalizeStockPurchasing(raw).data;this.selected='';this.model=null;this.tab='quotes';this.extraOpen.clear();}
  group(){return this.r?.stockPlan.groups.find(g=>g.selectionKey===this.groupKey)??this.r?.stockPlan.groups[0];}
  nextID(){let n=1;while(this.data.offers.some(o=>o.id==='L'+n))n++;return 'L'+n;}
  create(kind='offcut',stock=null){const g=this.group(),o={id:this.nextID(),kind,name:'',supplier:'',note:'',material:g?.materialKnown?g.material:'',thickness:g?.thickness??null,density:g?.density??null,length:stock?.stockLength??null,width:stock?.stockWidth??null,quantity:kind==='standard'?null:1,unitPrice:null,fee:0};this.data.offers.push(o);this.selected=o.id;this.tab='quotes';return o;}
  edit(e,commit){const el=e.target;if(!el.matches('[data-offer-field],[data-supply-currency]'))return;e.stopPropagation();this.model=null;
    if(el.hasAttribute('data-supply-currency')){if(!commit)return;this.data.currency=el.value;for(const o of this.data.offers){o.unitPrice=null;o.fee=0;}this.data.plans=[];this.notify('已更換幣別，原報價已清空；請重新填價，程式不換算匯率。');}
    else{const o=this.data.offers.find(o=>o.id===this.selected);if(!o)return;const k=el.dataset.offerField;o[k]=el.tagName==='INPUT'&&el.type==='number'?(el.validity.badInput?'invalid':el.value===''?null:Number(el.value)):el.value;}
    // Preserve input nodes during calculation so blur cannot swallow the next click or Tab.
    this.preserveEditor=el.hasAttribute('data-offer-field');try{this.onChange();}finally{this.preserveEditor=false;}
  }
  click(e){const b=e.target.closest('button');if(!b||!this.root.contains(b))return;e.stopPropagation();
    if(b.dataset.supplyTab){this.tab=b.dataset.supplyTab;if(this.tab==='compare'){this.model=null;this.render(this.r);this.compare();}else this.render(this.r);return;}
    if(b.hasAttribute('data-supply-compare')){this.compare();return;}
    if(b.dataset.supplyGroup||b.dataset.supplyEditGroup){this.groupKey=decodeURIComponent(b.dataset.supplyGroup??b.dataset.supplyEditGroup);this.selected='';if(b.dataset.supplyEditGroup)this.tab='quotes';this.render(this.r);return;}
    if(b.hasAttribute('data-offer-filter')){this.showAll=!this.showAll;this.render(this.r);return;}
    if(b.dataset.offerSelect){this.selected=b.dataset.offerSelect;const o=this.data.offers.find(x=>x.id===this.selected),g=this.r.stockPlan.groups.find(g=>materialKey(g.material)===materialKey(o.material)&&g.thickness===o.thickness&&(o.density===null||o.density===g.density));if(g)this.groupKey=g.selectionKey;this.render(this.r);return;}
    if(b.hasAttribute('data-offer-add')){if(this.data.offers.length>=120){this.notify('最多 120 筆料源，請移除已不用的項目。');return;}this.create();this.onChange();this.root.querySelector('[data-offer-field="length"]')?.focus();return;}
    if(b.hasAttribute('data-offer-presets')){const g=this.group();if(!g?.materialKnown){this.notify('請先填槽體／分件材質，才能新增同材同厚整張報價。');return;}for(const stock of TANK_STOCKS)if(!this.data.offers.some(o=>materialKey(o.material)===materialKey(g.material)&&o.thickness===g.thickness&&o.density===g.density&&o.kind==='standard'&&o.width===stock.stockWidth&&o.length===stock.stockLength)&&this.data.offers.length<120)this.create('standard',stock);this.onChange();return;}
    if(b.hasAttribute('data-offer-delete')){this.data.offers=this.data.offers.filter(o=>o.id!==this.selected);this.selected='';this.onChange();return;}
    if(b.dataset.offerKind){const o=this.data.offers.find(x=>x.id===this.selected);if(o){o.kind=b.dataset.offerKind;if(o.kind!=='standard'&&o.quantity===null)o.quantity=1;this.onChange();}return;}
    if(b.dataset.offerSize){const s=TANK_STOCKS.find(x=>x.id===b.dataset.offerSize),o=this.data.offers.find(x=>x.id===this.selected);if(o&&s){o.length=s.stockLength;o.width=s.stockWidth;this.onChange();}return;}
    if(b.dataset.supplyApply){try{const patch=applyPurchaseOption(this.r,decodeURIComponent(b.dataset.supplyApply),b.dataset.mode);this.data=structuredClone(patch.stockPurchasing);this.tab='applied';this.model=null;this.onApply(patch);this.notify('已套用採購排法，原板、BOM、重量與金額已同步；供料庫存不會重複扣除。');}catch(err){this.notify(err.message);}return;}
    if(b.hasAttribute('data-supply-reset')){this.data.plans=this.data.plans.filter(p=>p.key!==decodeURIComponent(b.dataset.supplyReset));this.onChange();}
  }
  compare(){if(this.comparing)return;this.comparing=true;const r=this.r;this.root.querySelector('[data-supply-body]').innerHTML='<p role="status">正在逐張排料，比較可供數量與報價…</p>';setTimeout(()=>{try{if(this.r===r){this.model=compareStockPurchases(r);this.tab='compare';}}catch(err){this.notify('比較未完成：'+err.message);}finally{this.comparing=false;this.render(this.r);}},30);}
  focus(field){this.tab='quotes';const [,id,key]=String(field).split('.');if(id&&this.data.offers.some(o=>o.id===id))this.selected=id;this.render(this.r);this.root.scrollIntoView({block:'start',behavior:'smooth'});this.root.querySelector(`[data-offer-field="${key??'unitPrice'}"]`)?.focus();}
  editor(o){
    const field=(key,label,type='number',hint='')=>`<label>${label}<input data-offer-field="${key}" type="${type}" ${type==='number'?`min="0" step="${key==='quantity'?'1':['unitPrice','fee'].includes(key)?'0.01':'any'}" inputmode="decimal"`:'maxlength="200"'} value="${esc(val(o[key]))}">${hint?'<small>'+hint+'</small>':''}</label>`;
    const invalid=normalizeStockPurchasing({...this.data,offers:[o],plans:[]});
    return `<div class="supply-editor"><header><h4>${esc(o.id)} · 編輯供料</h4><button type="button" data-offer-delete class="supply-remove">移除此筆</button></header><div class="supply-kinds">${Object.entries(SUPPLY_KINDS).map(([id,name])=>`<button type="button" data-offer-kind="${id}" aria-pressed="${o.kind===id}">${name}</button>`).join('')}</div><div class="supply-fields">${field('material','材質（依材證／報價單）','text')}${field('thickness','板厚 mm')}</div><div class="supply-size-presets">${TANK_STOCKS.map(s=>`<button type="button" data-offer-size="${s.id}">${s.label}</button>`).join('')}</div><div class="supply-fields">${field('length','可用長 mm')}${field('width','可用寬 mm')}${field('quantity','可供數量（片）','number',o.kind==='standard'?'留空＝不限量供應；請確認供應商供量':'有限數量必填；0 表示目前無料')}${field('unitPrice','每張／片報價 '+esc(this.data.currency),'number','留空＝待報價；自有料填 0，金額取兩位小數')}</div><p class="tank-note">餘板尺寸填已避開缺角、孔洞與受損邊的可用矩形；程式不在孔洞內套料。</p><details class="supply-extra" ${this.extraOpen.has(o.id)?'open':''}><summary>供應商、一次費用與其他資訊</summary><div class="supply-fields">${field('name','料號／名稱','text')}${field('supplier','供應商／庫位','text')}${field('fee','本筆訂購一次費用 '+esc(this.data.currency),'number','裁切／運費合計；留空＝無額外費，勿重複計入單價')}${field('density','密度 kg/m³','number','可留空；同材同厚有多種密度時，必須指定配對')}</div><label>備註<textarea data-offer-field="note" maxlength="500">${esc(o.note)}</textarea></label></details><div data-offer-messages>${invalid.issues.map(x=>'<p class="supply-warning">'+esc(x.message)+'</p>').join('')}${invalid.pending.length?'<p class="supply-warning">'+esc(invalid.pending[0].message)+'；填完後才能參與金額比較。</p>':''}</div></div>`;
  }
  render(r){
    if(!r?.valid||!r.stockPlan){this.root.replaceChildren();return;}if(this.r!==r)this.model=null;this.r=r;
    if(this.preserveEditor&&this.tab==='quotes'&&this.root.querySelector('.supply-editor')){const messages=this.root.querySelector('[data-offer-messages]'),o=this.data.offers.find(x=>x.id===this.selected),n=normalizeStockPurchasing({...this.data,offers:o?[o]:[],plans:[]});if(messages)messages.innerHTML=[...n.issues,...n.pending].map(x=>'<p class="supply-warning">'+esc(x.message)+'</p>').join('');const card=this.root.querySelector(`[data-offer-select="${this.selected}"]`);if(card&&o){card.querySelector('span').textContent=(o.material||'材質待填')+' · t'+fmt(o.thickness)+' mm';card.querySelector('small').textContent=(o.length&&o.width?fmt(o.length)+' × '+fmt(o.width)+' mm':'尺寸待填')+' · '+money(o.unitPrice,this.data.currency);}return;}
    const previous=this.root.querySelector('.supply-extra');if(previous&&this.renderedOffer){if(previous.open)this.extraOpen.add(this.renderedOffer);else this.extraOpen.delete(this.renderedOffer);}
    const g=this.group();if(g)this.groupKey=g.selectionKey;
    const matches=o=>!g||materialKey(o.material)===materialKey(g.materialKnown?g.material:'')&&o.thickness===g.thickness;
    let selected=this.data.offers.find(o=>o.id===this.selected);if(!selected){selected=this.data.offers.find(matches);this.selected=selected?.id??'';}
    const visibleOffers=this.showAll?this.data.offers:this.data.offers.filter(o=>matches(o)||o.id===this.selected);
    const lines=supplyLines(r.sheets,this.data.offers),known=r.stockPlan.knownCost,unpriced=r.stockPlan.unpricedSheets;
    let body='';
    if(this.tab==='quotes')body=`<div class="supply-quote-layout"><aside><div class="supply-offer-list">${visibleOffers.map(o=>`<button type="button" data-offer-select="${esc(o.id)}" aria-pressed="${this.selected===o.id}"><strong>${esc(o.id+' '+(o.name||SUPPLY_KINDS[o.kind]))}</strong><span>${esc(o.material||'材質待填')} · t${fmt(o.thickness)} mm</span><small>${o.length&&o.width?fmt(o.length)+' × '+fmt(o.width)+' mm':'尺寸待填'} · ${Number.isFinite(o.unitPrice)?money(o.unitPrice,this.data.currency):'待報價'}</small></button>`).join('')||'<p class="tank-note">先選材料組，再填手邊可買的料。報價只記在本專案。</p>'}</div>${this.data.offers.length>this.data.offers.filter(matches).length?`<button type="button" data-offer-filter class="supply-filter">${this.showAll?'只看這組料源':'看全部料源（'+this.data.offers.length+'）'}</button>`:''}<button type="button" data-offer-add>＋ 餘板／裁切料</button><button type="button" data-offer-presets class="tank-secondary">＋ 3 種整張板報價</button></aside>${selected?this.editor(selected):'<div class="supply-empty"><svg viewBox="0 0 240 110" aria-hidden="true"><rect x="15" y="12" width="140" height="82" rx="5" fill="#d9e8e0" stroke="#608975"/><path d="M72 12v82M15 57h57" stroke="#fff" stroke-width="4"/><rect x="173" y="46" width="54" height="48" rx="3" fill="#e8cda4" stroke="#b48139"/></svg><h4>整張、餘板，放在一起比</h4><p>填可用矩形尺寸、實際數量與每片報價，才知道怎麼買比較省。</p><button type="button" data-offer-add>加入第一筆料源</button></div>'}</div><div class="supply-next"><span>空白報價不算免費，餘板數量不會當成無限。</span><button type="button" data-supply-tab="compare">比一比怎麼買 →</button></div>`;
    else if(this.tab==='compare'){const model=this.model,item=model?.groups.find(x=>x.group.selectionKey===this.groupKey);body=item?`<div class="supply-comparison-heading"><div><h4>${esc(g.material)} · t${fmt(g.thickness)} mm</h4><p>${item.saving===null?'整張報價未齊，暫時不計省多少錢。':'與已報價的整張方案比，板料可少花 '+money(item.saving,this.data.currency)+'。'}${item.incomplete?' '+item.incomplete+' 筆供料資料／報價未齊或無庫存，未當成免費料。':''}</p></div><button type="button" data-supply-compare class="tank-secondary">重新比較</button></div>${supplyOptionMarkup(item,this.data.currency)}<p class="tank-note">${model.partial?'目前只比已確認毛坯；仍有分件備料待補，金額不代表全槽採購總價。 ':''}${item.limited?'本次已達搜尋範圍限制，可能還有更省的排法。 ':''}按每張／片報價＋每筆供料的一次費用；不同材質、板厚與密度不混用。只比較板料支出，不計未報價焊工、吊運、稅金或廢料回收價；未保證全域最低。餘料重量為原料扣毛坯，毛坯內孔料／修邊另計。改分片須核對捲板與接縫工法。</p>`:`<div class="supply-empty"><p>尺寸、數量或報價有變動，請重新排料比較。</p><button type="button" data-supply-compare>開始比較採購方案</button></div>`;}
    else body=`<div class="supply-applied"><header><div><h4>已套用採購清單</h4><p>${lines.length?'已計 '+money(known,this.data.currency):'尚未套用報價排法'}${unpriced?' · 另有 '+unpriced+' 張待報價':''}</p></div><button type="button" data-supply-tab="compare">比較其他買法</button></header>${r.stockPlan.purchasePending.map(x=>'<p class="supply-warning">'+esc(x.message)+'</p>').join('')}${lines.map(l=>`<article><div><strong>${esc(l.id+' '+(l.name||SUPPLY_KINDS[l.kind]))}</strong><p>${esc(l.material)} · t${fmt(l.thickness)} · ${fmt(l.length)} × ${fmt(l.width)} mm</p><small>${l.used} 張／片 · 原板 #${l.sheetIDs.join('、#')}${l.remaining===null?'':' · 供料尚餘 '+l.remaining+' 片'}</small></div><strong>${money(l.subtotal,this.data.currency)}</strong></article>`).join('')}${this.data.plans.length?'<details><summary>取消指定採購排法</summary>'+this.data.plans.map(p=>`<button type="button" data-supply-reset="${encodeURIComponent(p.key)}" class="tank-secondary">取消 ${esc(r.stockPlan.groups.find(g=>g.selectionKey===p.key)?.material??'失效材料組')} 方案，回到整張估排</button>`).join('')+'</details>':''}<p class="tank-note">金額僅含本次已排入且已報價的板料。供料餘量＝填報可供量−本次採用量；重算、存檔及列印不會再扣庫存。未套用的報價不計入採購單。</p></div>`;
    this.renderedOffer=selected?.id;this.root.innerHTML=`<section class="tank-supply"><header class="supply-heading"><div><span class="workbench-eyebrow">STOCK & QUOTES</span><h3>手邊的料，怎麼買比較省？</h3><p>先填供料 → 比較買法 → 套用到排料與 BOM</p></div><label>報價幣別<select title="更換幣別會清空原報價，須重新填價" data-supply-currency aria-label="報價幣別">${['TWD','USD','CNY','JPY','EUR'].map(c=>`<option ${c===this.data.currency?'selected':''}>${c}</option>`).join('')}</select></label></header><div class="supply-tabs" role="group" aria-label="採購工作"><button type="button" data-supply-tab="quotes" aria-pressed="${this.tab==='quotes'}">1 填供料／報價 <small>${this.data.offers.length}</small></button><button type="button" data-supply-tab="compare" aria-pressed="${this.tab==='compare'}">2 比採購方案</button><button type="button" data-supply-tab="applied" aria-pressed="${this.tab==='applied'}">3 已套用清單</button></div><div class="supply-group-list" role="group" aria-label="選擇報價材料組">${r.stockPlan.groups.map(group=>`<button type="button" data-supply-group="${encodeURIComponent(group.selectionKey)}" aria-pressed="${group.selectionKey===this.groupKey}">${esc(group.material)} <b>t${fmt(group.thickness)}</b>${group.density!==g?.density?' · ρ'+fmt(group.density):''}</button>`).join('')}</div><div data-supply-body>${body}</div></section>`;
  }
}
